    [Fact]
    public void All25SourceRecordsAnd18TableKeysProduceEveryScalarStageAndHandValue()
    {
        using var profiles = JsonDocument.Parse(PilotProfilesJson); using var provenance = JsonDocument.Parse(PilotProvenanceJson);
        using var manifest = JsonDocument.Parse(PilotSourceManifestJson); using var pins = JsonDocument.Parse(PilotSeedVectorsJson);
        using var vectors = JsonDocument.Parse(ProfileVectorsJson);
        var cohort = profiles.RootElement.EnumerateArray().Select(x => new RetailNpcSourceProfile(x)).ToDictionary(x => x.NpcId);
        var dataset = new RetailNpcStaticDataset(PilotDatasetId, PilotManifestHash, cohort, 63287, 117, 0,
            ImmutableArray<RetailNpcArtifactReceipt>.Empty, provenance.RootElement, manifest.RootElement);
        var rows = vectors.RootElement.GetProperty("vectors"); Assert.Equal(450, rows.GetArrayLength()); Assert.Equal(25, cohort.Count);
        foreach (var v in rows.EnumerateArray())
        {
            int id = v.GetProperty("npc_id").GetInt32();
            var projected = RetailNpcTemplateProjection.Project(dataset, id, new(PilotDatasetId, PilotManifestHash, "USA"));
            Assert.True(projected.Success, string.Join(";", projected.Issues)); var source = projected.Inputs!;
            var pin = pins.RootElement.EnumerateArray().Single(x => x.GetProperty("id").GetInt32() == id);
            Assert.Equal(pin.GetProperty("raw_sha256").GetString(), source.Receipt.RawRecordSha256);
            Assert.Equal(pin.GetProperty("file_sha256").GetString(), source.Receipt.SourceFileSha256);
            Assert.Equal(pin.GetProperty("raw_tree_sha256").GetString(), Hash(Encoding.UTF8.GetBytes(source.RawRecord.GetRawText())));
            Assert.Equal(pin.GetProperty("byte_start").GetInt64(), source.Receipt.ByteStart); Assert.Equal(pin.GetProperty("byte_end").GetInt64(), source.Receipt.ByteEndExclusive);
            var table = ActualTable(source); var selected = Selection(table, v.GetProperty("name").GetString()!, v.GetProperty("rank").GetByte());
            var pairs = vectors.RootElement.GetProperty("varying_modifier_pairs").EnumerateArray()
                .Select(x => new RetailNpcModifierPairInput(x.GetProperty("index").GetInt32(), x.GetProperty("percent").GetInt32(), x.GetProperty("flat").GetInt32())).ToArray();
            var level = Level(source); var aggregate = Aggregate(source, level, pairs); var context = Context(source, level, selected, aggregate);
            var result = RetailNpcVirtualProfileConstruction.Construct(source, level, selected, aggregate, context);
            Assert.True(result.Success, string.Join(";", result.Issues)); var plan = result.Value!;
            Assert.Equal(85, plan.Scalars.Count); Assert.Equal(17, plan.Helpers.Count); Assert.Equal(22, plan.PreEffectShadows.Count);
            foreach (var value in v.GetProperty("conditional_effective_scalars").EnumerateObject())
                Assert.Equal(value.Value.GetInt64(), plan.Scalars[value.Name].Value);
            foreach (var value in v.GetProperty("scalar_baselines").EnumerateObject()) Assert.Equal(value.Value.GetInt64(), plan.Scalars[value.Name].Baseline);
            foreach (var value in v.GetProperty("transforms").EnumerateObject())
            {
                var actual = plan.Helpers[value.Name]; Assert.Equal(value.Value.GetProperty("full_helper").GetInt64(), actual.FullResult);
                Assert.Equal(value.Value.GetProperty("actor_baseline").GetInt64(), actual.ActorBaseline);
            }
            foreach (var value in v.GetProperty("pre_effect_shadow_writes").EnumerateObject()) Assert.Equal(value.Value.GetInt64(), plan.PreEffectShadows[value.Name]);
            foreach (var value in v.GetProperty("common_tail_writes").EnumerateObject()) Assert.Equal(value.Value.GetInt64(), plan.CommonTail[value.Name]);
            Assert.Equal(v.GetProperty("initial_hp").GetInt64(), plan.InitialHpOnSet);
            Assert.Equal(v.GetProperty("initial_mp_diagnostic").GetInt64(), plan.InitialMpOnSetDiagnostic);
            Assert.Equal(v.GetProperty("original_delay").GetInt64(), plan.Delay.OriginalWord); Assert.Equal(v.GetProperty("current_delay").GetInt64(), plan.Delay.Value);
            Assert.Equal(v.GetProperty("current_hit_count").GetInt64(), plan.Count.Value);
            Assert.Equal(v.GetProperty("right_minimum").GetInt64(), plan.RightMinimum); Assert.Equal(v.GetProperty("right_maximum").GetInt64(), plan.RightMaximum);
            Assert.Equal(v.GetProperty("auxiliary_actor_writes").GetProperty("0x14e6").GetInt64(), plan.CancelLevel);
            Assert.Equal(v.GetProperty("auxiliary_actor_writes").GetProperty("0x1685").GetInt64(), plan.DpReduce);
            Assert.Equal(0, plan.OffhandCount); Assert.Equal(0, plan.OffhandMinimum); Assert.Equal(0, plan.OffhandMaximum);
            Assert.Equal(0, plan.EffectiveMaxMpSeedDiagnostic); Assert.Equal(0, plan.FreshMpRegenerationDiagnostic);
            Assert.False(plan.RuntimeObservationVerified); Assert.False(plan.EffectiveActorValueVerified); Assert.False(plan.ActivationReady);
            Assert.Equal(RetailNpcSourcePresence.Absent, plan.TemplateValues["stat_ratio"].Presence);
            Assert.Contains(plan.TemplateValues["stat_ratio"].History, h => h.Rule.Contains("loaded-level-table", StringComparison.Ordinal));
            Assert.Equal(3, plan.AbnormalMerges.Count(x => x.IgnoredNamelessZero));
            Assert.Equal("stat_ratio", plan.OrderedWrites.First(x => x.Stage == "CalcSecondEffects").Field);
            Assert.Equal("hp_regen", plan.OrderedWrites.Last(x => x.Stage == "CalcSecondEffects").Field);
            Assert.False(RetailNpcInitializationRules.Assess(source).CanConstructEffectiveInputs);
        }
    }

    [Fact]
    public void EveryIndependentIntegerHelperNarrowingDelayAndAuxiliaryOracleIsChecked()
    {
        using var document = JsonDocument.Parse(IntegerBoundariesJson); var root = document.RootElement;
        foreach (var v in root.GetProperty("profile_helper").EnumerateArray())
        {
            bool hp = v.GetProperty("hp").GetBoolean();
            var h = RetailNpcVirtualProfileConstruction.Helper(hp ? "max_hp" : "hp_regen", hp ? 0x30 : 0x38, 32, v.GetProperty("base").GetInt64(),
                new(v.GetProperty("flat").GetInt32(), v.GetProperty("percent").GetInt32()));
            Assert.Equal(v.GetProperty("expected").GetInt64(), h.FullResult);
        }
        foreach (var v in root.GetProperty("delay").EnumerateArray())
        {
            var delay = RetailNpcVirtualProfileConstruction.Delay(v.GetProperty("original_word").GetInt64(), new(29, v.GetProperty("percent").GetInt32(), v.GetProperty("flat").GetInt32()));
            Assert.Equal(v.GetProperty("expected").GetInt64(), delay.Value);
        }
        foreach (var v in root.GetProperty("auxiliary_fields").EnumerateArray())
        {
            var fixture = new Fixture(); string field = v.GetProperty("field").GetString()!;
            if (v.GetProperty("source_value").ValueKind != JsonValueKind.Null) fixture.Set(field, v.GetProperty("source_value").GetInt32());
            var p = Build(fixture.Inputs()); Assert.Equal(v.GetProperty("expected").GetInt64(), field == "cancel_level" ? p.CancelLevel : p.DpReduce);
        }
        var narrowed = new Fixture(); narrowed.Set("min_damage", 65536); narrowed.Set("max_damage", -1); narrowed.Set("hit_count", 256);
        var n = Build(narrowed.Inputs()); Assert.Equal(0, n.RightMinimum); Assert.Equal(65535, n.RightMaximum); Assert.Equal(0, n.Helpers["hit_count"].ActorBaseline);
        var element = new Fixture(); element.Add(Node("first_level_attr", null, Node("elemental_defend_water", "32767")));
        Assert.Equal(-2, Build(element.Inputs(), "<ed_water_bonus>200%</ed_water_bonus>").Scalars["elemental_defend_water"].Value);
    }

    [Fact]
    public void RawMagicCritZeroMagicOperandRawCountAndConcentrationAreDistinctFromTransformedActorBases()
    {
        var f = new Fixture(); f.Set("critical", 100); f.Set("magical_critical", 500); f.Set("concentration", 500); f.Set("hit_count", 5);
        var pairs = Pairs(); foreach (int index in new[] {34,40,41,35}) pairs[index] = new(index, 100, 0);
        var p = Build(f.Inputs(), "<critical>10</critical><magical_critical>1000</magical_critical><concentration>10</concentration><hit_count>1</hit_count>", pairs);
        Assert.Equal((10L,500L,510L), (p.Scalars["critical"].Baseline,p.Scalars["critical"].PercentOperand,p.Scalars["critical"].Value));
        Assert.Equal((1000L,0L,1000L), (p.Scalars["magical_critical"].Baseline,p.Scalars["magical_critical"].PercentOperand,p.Scalars["magical_critical"].Value));
        Assert.Equal(510, p.Scalars["concentration"].Value); Assert.Equal((1L,5L,6L), (p.Count.Baseline,p.Count.PercentOperand,p.Count.Value));
        Assert.Equal(500, p.PreEffectShadows["0x181c"]); Assert.Equal(0, p.PreEffectShadows["0x1836"]);
    }

    [Theory]
    [InlineData(0)] [InlineData(1)] [InlineData(2)] [InlineData(3)] [InlineData(4)] [InlineData(5)] [InlineData(6)] [InlineData(7)] [InlineData(8)]
    public void EveryNativeNarrowingElementAndUnequalOperandOracleIsPreserved(int ordinal)
    {
        using var document=JsonDocument.Parse(IntegerBoundariesJson);var v=document.RootElement.GetProperty("narrowing_and_unequal_operands")[ordinal];
        string name=v.GetProperty("case").GetString()!;
        if(v.TryGetProperty("helper",out var h))
        {var actual=RetailNpcVirtualProfileConstruction.Helper("hp_regen",0x38,v.GetProperty("width").GetInt32(),h.GetInt64(),new(0,100));Assert.Equal(v.GetProperty("expected").GetInt64(),actual.ActorBaseline);return;}
        if(v.TryGetProperty("expected_set_word",out var word))
        {long full=RetailNpcVirtualProfileConstruction.ElementFull(v.GetProperty("base").GetInt16(),new(v.GetProperty("flat").GetInt32(),v.GetProperty("percent").GetInt32()));
            Assert.Equal(word.GetInt64(),unchecked((short)full));if(v.TryGetProperty("expected_effective",out var e))Assert.Equal(e.GetInt64(),Math.Clamp((int)unchecked((short)full),-1300,1300));return;}
        var f=new Fixture();f.Set("magical_critical",500);f.Set("concentration",500);f.Set("hit_count",5);
        int index=name.StartsWith("physical",StringComparison.Ordinal)?34:name.StartsWith("magical",StringComparison.Ordinal)?40:name.StartsWith("concentration",StringComparison.Ordinal)?41:35;
        var pairs=Pairs();pairs[index]=new(index,v.GetProperty("percent").GetInt32(),v.GetProperty("flat").GetInt32());
        var p=Build(f.Inputs(),"<critical>10</critical><magical_critical>1000</magical_critical><concentration>10</concentration><hit_count>1</hit_count>",pairs);
        long actualValue=index==35?p.Count.Value:p.Scalars[index==34?"critical":index==40?"magical_critical":"concentration"].Value;
        Assert.Equal(v.GetProperty("expected").GetInt64(),actualValue);
    }

