    [Theory]
    [InlineData("hash")] [InlineData("length")] [InlineData("traversal")] [InlineData("empty")] [InlineData("unknown")]
    [InlineData("duplicate-key")] [InlineData("missing-rank")] [InlineData("rank-zero")] [InlineData("rank-ten")]
    [InlineData("name-long")] [InlineData("name-nonascii")] [InlineData("empty-value")] [InlineData("overflow")]
    [InlineData("crt-tail")] [InlineData("truncated")] [InlineData("duplicate-attribute")] [InlineData("external")]
    public void WholeTableLateErrorsAndSourcePinsNeverPublishPartialRecords(string failure)
    {
        var source=new Fixture().Inputs();string xml=Xml("");
        xml=failure switch {
            "empty"=>"<dynamiccreations/>","unknown"=>Xml("<future>1</future>"),"duplicate-key"=>xml.Replace("rank=\"9\"","rank=\"1\""),
            "missing-rank"=>xml.Replace("<attr_set_name attr_set_name=\"fixture\" rank=\"9\"></attr_set_name>",""),"rank-zero"=>xml.Replace("rank=\"9\"","rank=\"0\""),"rank-ten"=>xml.Replace("rank=\"9\"","rank=\"10\""),
            "name-long"=>xml.Replace("fixture",new('a',81)),"name-nonascii"=>xml.Replace("fixture","fïxture"),
            "empty-value"=>Xml("<max_hp/>"),"overflow"=>Xml("<max_hp>2147483648%</max_hp>"),"crt-tail"=>Xml("<max_hp>100%tail</max_hp>"),
            "truncated"=>xml[..^1],"duplicate-attribute"=>xml.Replace("rank=\"9\"","rank=\"9\" rank=\"9\""),
            "external"=>"<!DOCTYPE dynamiccreations SYSTEM 'file:///never-open'>"+xml,_=>xml};
        byte[] bytes=Encoding.UTF8.GetBytes(xml);var policy=Policy(source,bytes);
        if(failure=="hash")policy=policy with{ExpectedSourceSha256=new('f',64)};
        if(failure=="length")policy=policy with{ExpectedSourceBytes=bytes.Length+1};
        if(failure=="traversal")policy=policy with{SelectedRelativePath="../DynamicCreation.xml"};
        var r=RetailNpcVirtualProfileTable.Admit(bytes,policy);Assert.False(r.Success);Assert.Null(r.Value);
    }

    [Fact]
    public void DefaultsExplicitZeroAliasLastWriteAndIgnoredRawFieldsRemainLossless()
    {
        var source=new Fixture().Inputs();var table=Table(source,"<ed_water_bonus>200%</ed_water_bonus><er_water_bonus>7</er_water_bonus><max_hp>0%</max_hp><physical_attack><unknown>opaque</unknown></physical_attack>");
        var d=table.Records[0];Assert.Equal(new RetailNpcVirtualPair(7,0),d.Pairs[0]);Assert.Equal(new RetailNpcVirtualPair(0,0),d.Pairs[0x30]);Assert.Equal(new RetailNpcVirtualPair(0,100),d.Pairs[0x38]);
        Assert.Equal(4,d.Occurrences.Length);Assert.True(d.Occurrences[^1].Ignored);Assert.Contains("opaque",d.Occurrences[^1].RawXml);
        Assert.Equal(new[]{0xbc,0xbd,0xbe,0xbf},d.UnknownPaddingOffsets.ToArray());Assert.Equal(32,d.Pairs.Count);
        var p=Build(source,"<max_hp>0%</max_hp>");Assert.Equal(0,p.InitialHpOnSet);Assert.Equal(1,p.Scalars["max_hp"].Value);
        var explicitRatio=new Fixture();explicitRatio.Set("stat_ratio",0);var zero=Build(explicitRatio.Inputs());
        Assert.Equal(RetailNpcSourcePresence.ExplicitZero,zero.TemplateValues["stat_ratio"].Presence);Assert.Equal(1000,zero.TemplateValues["stat_ratio"].TemplateValue);
        Assert.DoesNotContain(zero.TemplateValues["stat_ratio"].History,x=>x.Rule.Contains("loaded-level-table",StringComparison.Ordinal));
        var exp=Table(source,"<exp>9223372036854775807</exp><exp>4294967297%</exp>").Records[0];
        Assert.Equal(0,exp.ExpFlat);Assert.Equal(1,exp.ExpPercent);Assert.Equal(long.MaxValue,exp.Occurrences[0].ParsedValue);
    }

