    [Fact]
    public void PrimaryCancelMpDiagnosticsAndRawIgnoredAttacksNeverBecomeOtherEffectiveFields()
    {
        var f=new Fixture();f.Set("physical_attack",999999);f.Set("magical_attack",888888);f.Set("min_damage",50);f.Set("max_damage",75);
        f.Set("max_mp",300);f.Set("mp_regen",9);f.Set("cancel_level",101);f.Add(Node("first_level_attr",null,Node("str","7")));
        var pairs=Pairs();pairs[6]=new(6,int.MaxValue,int.MaxValue);pairs[42]=new(42,int.MaxValue,int.MaxValue);
        pairs[110]=new(110,int.MaxValue,1500);pairs[152]=new(152,int.MinValue,-1500);
        var p=Build(f.Inputs(),"<max_mp>200%</max_mp>",pairs);
        Assert.Equal(7,p.Scalars["str"].Value);Assert.Equal(101,p.CancelLevel);Assert.Equal(50,p.RightMinimum);Assert.Equal(75,p.RightMaximum);
        Assert.Equal(600,p.InitialMpOnSetDiagnostic);Assert.Equal(0,p.EffectiveMaxMpSeedDiagnostic);Assert.Equal(0,p.FreshMpRegenerationDiagnostic);
        Assert.Equal(1000,p.Scalars["heal_skill_boost"].Value);Assert.Equal(-1000,p.Scalars["mp_heal_skill_boost"].Value);
        Assert.Null(p.Scalars["heal_skill_boost"].Percent);Assert.Equal("999999",Assert.Single(p.Source.RawPhysicalAttack.RawValues));
        Assert.Equal("888888",Assert.Single(p.Source.RawMagicalAttack.RawValues));Assert.False(p.ActivationReady);
    }

