    [Fact]
    public void NamesRegisterCaseInsensitivelyInSourceOrderAndCapacityIsBounded()
    {
        var source=new Fixture().Inputs();byte[] bytes=Encoding.UTF8.GetBytes(Xml("").Replace("fixture","MixedCase"));
        var admitted=RetailNpcVirtualProfileTable.Admit(bytes,Policy(source,bytes));Assert.True(admitted.Success);var t=admitted.Value!;
