    [Fact]
    public void All12IndependentActionBitOraclesAndCurrentCritSelectionAreExplicit()
    {
        using var document=JsonDocument.Parse(ActionVectorsJson);
        foreach(var v in document.RootElement.GetProperty("vectors").EnumerateArray())
        {
            var pairs=Pairs();pairs[38]=new(38,v.GetProperty("effect_percent").GetInt32(),v.GetProperty("effect_flat").GetInt32());
            int pct=v.GetProperty("profile_percent").GetInt32(),flat=v.GetProperty("profile_flat").GetInt32();
            var steps=new List<RetailNpcVirtualFloatStep>();
            uint rangeBits=unchecked((uint)BitConverter.SingleToInt32Bits(v.GetProperty("source_range").GetSingle()));
            uint stage=RetailNpcVirtualProfileActionPlan.ComputeRangeStage(new(flat,pct),rangeBits,pairs[38],steps);
            Assert.Equal(Bits(v.GetProperty("expected_bits").GetString()!),stage);
            Assert.Equal(Bits(v.GetProperty("expected_profile_bits").GetString()!),steps.Single(x=>x.Operation=="profile-range-flat-add").Bits);
            Assert.Equal(Bits(v.GetProperty("expected_unclamped_bits").GetString()!),steps.Single(x=>x.Operation=="range-baseline-final-add").Bits);
            // Both-component mathematical stages are tested above; the strict XML
            // parser cannot construct them, so only representable pairs enter a full plan.
            if(pct!=0&&flat!=0)continue;
            string range=flat!=0?$"{flat}":$"{pct}%";
            var p=Build(new Fixture().Inputs(),$"<attack_range>{range}</attack_range>",pairs);
            byte[] image=new byte[24];BinaryPrimitives.WriteSingleLittleEndian(image.AsSpan(4),v.GetProperty("source_range").GetSingle());BinaryPrimitives.WriteInt32LittleEndian(image.AsSpan(20),100);
            var receipt=ActionReceipt(p,image);var c=ActionContext(p,receipt);
            var r=RetailNpcVirtualProfileActionPlan.PlanSelectedAction(p,image,receipt,c);Assert.True(r.Success,string.Join(";",r.Issues));
            Assert.Equal(Bits(v.GetProperty("expected_bits").GetString()!),r.Value!.RangeBits);Assert.False(r.Value.ActivationReady);
        }
        var f=new Fixture();f.Set("critical",10);f.Set("magical_critical",50);var a=Pairs();a[25]=new(25,200,-7);a[27]=new(27,-50,17);
        var profile=Build(f.Inputs(),pairs:a);byte[] record=new byte[24];BinaryPrimitives.WriteSingleLittleEndian(record.AsSpan(4),5);BinaryPrimitives.WriteInt32LittleEndian(record.AsSpan(20),100);
        var pin=ActionReceipt(profile,record);var physical=RetailNpcVirtualProfileActionPlan.PlanSelectedAction(profile,record,pin,ActionContext(profile,pin));
        var magical=RetailNpcVirtualProfileActionPlan.PlanSelectedAction(profile,record,pin,ActionContext(profile,pin) with{CurrentPhysicalFlag8e4=0});
        Assert.True(physical.Success);Assert.True(magical.Success);Assert.Equal(10u,physical.Value!.Writes["0x14b8"]);Assert.Equal(50u,magical.Value!.Writes["0x14b8"]);
        Assert.Equal(0x40000000u,physical.Value.Writes["0x8dc"]);Assert.Equal(0xbf000000u,magical.Value.Writes["0x8e0"]);
        Assert.Equal(unchecked((uint)-7),physical.Value.Writes["0x14d4"]);Assert.Equal(17u,magical.Value.Writes["0x14d8"]);
    }

    [Theory]
    [InlineData("record")] [InlineData("extent")] [InlineData("selection")] [InlineData("epoch")] [InlineData("flag")]
    [InlineData("rne")] [InlineData("masked")] [InlineData("isa")] [InlineData("return")] [InlineData("nan")] [InlineData("subnormal")] [InlineData("range")]
    public void ActionRequiresAnIndependentMainImageAndEveryCurrentMathematicalCondition(string failure)
    {
        var p=Build(new Fixture().Inputs());byte[] image=new byte[24];BinaryPrimitives.WriteSingleLittleEndian(image.AsSpan(4),5);
        if(failure=="nan")BinaryPrimitives.WriteUInt32LittleEndian(image.AsSpan(4),0x7fc00000);
        if(failure=="subnormal")BinaryPrimitives.WriteUInt32LittleEndian(image.AsSpan(4),1);
        if(failure=="range")BinaryPrimitives.WriteSingleLittleEndian(image.AsSpan(4),65536);
        var receipt=ActionReceipt(p,image);var c=ActionContext(p,receipt);
        c=failure switch {"record"=>c with{ExpectedAction=receipt with{RecordSha256=new('f',64)}},"extent"=>c with{ExpectedAction=receipt with{RecordBytes=25}},
            "selection"=>c with{ExpectedAction=receipt with{SelectionIdentity=""}},"epoch"=>c with{ExpectedAction=receipt with{Epoch="other"}},
            "flag"=>c with{CurrentPhysicalFlag8e4=null},"rne"=>c with{Binary32NearestEven=null},"masked"=>c with{MaskedFloatingExceptions=false},
            "isa"=>c with{ConsumedInstructionsAvailable=null},"return"=>c with{NormalReturn=null},_=>c};
        receipt=c.ExpectedAction;
        var result=RetailNpcVirtualProfileActionPlan.PlanSelectedAction(p,image,receipt,c);Assert.False(result.Success);Assert.Null(result.Value);
    }

    private static uint Bits(string value)=>uint.Parse(value[2..],NumberStyles.HexNumber,CultureInfo.InvariantCulture);
    private static RetailNpcVirtualConstructionPlan Build(RetailNpcTemplateInputs source,string fields="",RetailNpcModifierPairInput[]? pairs=null,int kind=1)
    {var l=Level(source);var s=Selection(Table(source,fields));var a=Aggregate(source,l,pairs??Pairs());var c=Context(source,l,s,a,kind);
        var r=RetailNpcVirtualProfileConstruction.Construct(source,l,s,a,c);Assert.True(r.Success,string.Join(";",r.Issues));return r.Value!;}
    private static RetailNpcVirtualContext Context(RetailNpcTemplateInputs s,RetailNpcLevelRatioTableInputs l,RetailNpcVirtualSelection v,RetailNpcModifierAggregate a,int kind=1)
    {var domain=new RetailNpcVirtualDomain(true,true,kind,0,0,true,false,false);return new(s.Receipt,l.Receipt,v.Table.Receipt,v.Descriptor.SemanticSha256,v.NativeNameId,v.NativeRank,
        v.Registry.ContentSha256,Package,a.Receipt.ContentSha256,Epoch,RetailNpcModifierInputOrigin.FixedMathematicalFixture,null,domain,domain);}
    private static RetailNpcModifierPairInput[] Pairs()=>Enumerable.Range(0,161).Select(i=>new RetailNpcModifierPairInput(i,0,0)).ToArray();
    private static RetailNpcModifierAggregate Aggregate(RetailNpcTemplateInputs s,RetailNpcLevelRatioTableInputs l,RetailNpcModifierPairInput[] pairs)
    {byte[] bytes=new byte[1288];foreach(var p in pairs){BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(p.Index*8),p.Percent);BinaryPrimitives.WriteInt32LittleEndian(bytes.AsSpan(p.Index*8+4),p.Flat);}
        var r=RetailNpcOrdinaryScalarEvaluation.AdmitModifierAggregate(pairs,new(RetailNpcModifierInputOrigin.FixedMathematicalFixture,s.Receipt,l.Receipt.SourceSha256,Package,Hash(bytes),1288,Epoch,null,"explicit full mathematical161pairs"));
        Assert.True(r.Success,string.Join(";",r.Issues));return r.Aggregate!;}
